x_938076_backup_0_backup_scripts.script:
function makeFieldsManUpgradeEntitlement() {
	var gr = new GlideRecord('sys_dictionary');
	gr.addEncodedQuery('name=samp_upgraded_entitlement^mandatory=false^element=licensed_by^ORelement=upgrade_from'
		+ '^ORelement=num_rights');
	gr.query();
	while (gr.next()) {
		gr.setValue('mandatory', 'true');
		gr.update();
	}
}

makeFieldsManUpgradeEntitlement();
